// Interactive KRaft consensus playground.
//
// Loads the `krabka-playground` WASM module (a thin shim over Krabka's real
// deterministic consensus core) and drives it from the browser: render the
// cluster, inject faults, and step the in-memory message bus / timers while
// watching the cluster elect a leader, lose it, and recover. No backend.
//
// The WASM glue (`krabka_playground.js` / `_bg.wasm`) is generated by
// `playground/build.sh`; this file is the hand-written front-end.

import init, { Playground } from "./krabka_playground.js";

const SVG_NS = "http://www.w3.org/2000/svg";

// Role -> { css class, glyph } for the node badges. Matches the legend.
const ROLE_STYLE = {
  Leader: { cls: "leader", glyph: "♔" }, // ♔
  Follower: { cls: "follower", glyph: "⚑" }, // ⚑
  Candidate: { cls: "candidate", glyph: "☰" }, // ☰
  Prospective: { cls: "prospective", glyph: "☷" }, // ☷
  Unattached: { cls: "idle", glyph: "·" }, // ·
  Voted: { cls: "idle", glyph: "✓" }, // ✓
  Observer: { cls: "observer", glyph: "○" }, // ○
  Resigned: { cls: "idle", glyph: "—" }, // —
};

// Short glyphs for the timeline action kinds.
const ACTION_ICON = {
  Deliver: "→", // →
  Partition: "✂", // ✂
  Heal: "⛓", // ⛓
  Timeout: "⏰︎", // ⏰, forced to the flat text glyph like the others
  Elected: "♔", // ♔
  Append: "✎", // ✎
  Drop: "✕", // ✕
};

class PlaygroundUI {
  constructor(root) {
    this.root = root;
    this.pg = null;
    this.voters = 3;
    this.playing = false;
    this.timer = null;
    this.seenSteps = 0;
    this.speedMs = 650;
    this.build();
  }

  // ---- DOM scaffolding ------------------------------------------------------

  build() {
    this.root.innerHTML = "";
    this.root.classList.add("cp-ready");

    const controls = el("div", "cp-controls");

    this.sizeSel = el("select", "cp-select");
    this.sizeSel.setAttribute("aria-label", "Number of voters");
    for (const n of [3, 5]) {
      const o = document.createElement("option");
      o.value = String(n);
      o.textContent = `${n} voters`;
      this.sizeSel.appendChild(o);
    }
    this.sizeSel.value = String(this.voters);
    this.sizeSel.addEventListener("change", () => {
      this.voters = Number(this.sizeSel.value);
      this.reset();
    });

    this.playBtn = button("▶ Play", "cp-primary", () => this.togglePlay());
    this.stepBtn = button("Step", "", () => {
      this.pause();
      this.step();
    });
    this.settleBtn = button("Settle", "", () => {
      this.pause();
      this.pg.settle();
      this.render();
    });
    this.resetBtn = button("Reset", "", () => this.reset());

    controls.append(
      this.sizeSel,
      this.playBtn,
      this.stepBtn,
      this.settleBtn,
      this.resetBtn,
    );

    // Fault toolbar.
    const faults = el("div", "cp-faults");
    faults.append(
      label("Faults"),
      button("Partition leader", "", () => this.partitionLeader()),
      button("Heal", "", () => this.healAll()),
      button("Produce ✎", "", () => this.act(() => this.pg.append(1))),
      button("Drop next ✕", "", () => this.act(() => this.pg.drop_next())),
      button("Reorder bus", "", () => this.act(() => this.pg.reorder())),
      button("Duplicate next", "", () =>
        this.act(() => this.pg.duplicate_next()),
      ),
    );

    // Stage: cluster diagram + side timeline.
    const stage = el("div", "cp-stage");

    const diagramWrap = el("div", "cp-diagram-wrap");
    this.svg = document.createElementNS(SVG_NS, "svg");
    this.svg.setAttribute("class", "cp-diagram");
    // A group, not an img: the nodes inside are focusable buttons, and an img
    // role makes its children presentational.
    this.svg.setAttribute("role", "group");
    this.svg.setAttribute("aria-label", "KRaft cluster diagram");
    // Three layers so message labels always paint over the nodes.
    this.arcLayer = svgEl("g");
    this.nodeLayer = svgEl("g");
    this.labelLayer = svgEl("g", "cp-labels");
    this.svg.append(arrowMarker(), this.arcLayer, this.nodeLayer, this.labelLayer);
    diagramWrap.appendChild(this.svg);
    this.nodeEls = new Map();
    this.width = 0;
    // The viewBox is sized in screen pixels (see drawCluster), so text keeps
    // its size at every width; redraw when the column changes width.
    new ResizeObserver(() => {
      const w = this.svg.getBoundingClientRect().width;
      if (w > 0 && w !== this.width && this.lastSnap) this.drawCluster(this.lastSnap);
    }).observe(this.svg);

    this.status = el("div", "cp-status");
    diagramWrap.appendChild(this.status);

    const timelineWrap = el("div", "cp-timeline-wrap");
    timelineWrap.appendChild(label("Event timeline"));
    this.timeline = el("ol", "cp-timeline");
    timelineWrap.appendChild(this.timeline);

    stage.append(diagramWrap, timelineWrap);

    // Legend + hint.
    const legend = el("div", "cp-legend");
    for (const [role, { cls, glyph }] of Object.entries(ROLE_STYLE)) {
      if (role === "Voted" || role === "Resigned") continue; // fold into idle
      const item = el("span", `cp-legend-item cp-${cls}`);
      item.innerHTML = `<span class="cp-dot"></span>${glyph} ${role}`;
      legend.appendChild(item);
    }

    const hint = el("p", "cp-hint");
    hint.innerHTML =
      "Click a node, or Tab to it and press Enter, to partition it (again to heal). " +
      "<strong>Step</strong> delivers one bus message or fires the next timer; " +
      "<strong>Play</strong> auto-steps. Everything runs the real deterministic " +
      "engine, compiled to WebAssembly.";

    // Screen-reader announcements for elections, partitions and drops. The
    // per-tick status line and the timeline stay silent: they change too often.
    this.live = el("div", "cp-sr");
    this.live.setAttribute("role", "status");
    this.live.setAttribute("aria-live", "polite");
    this.pending = [];
    this.announceTimer = null;
    this.prev = null;

    this.root.append(controls, faults, stage, legend, hint, this.live);
  }

  // Queue a short sentence; sentences that arrive within the same 1.5 s window
  // are spoken together, so Play cannot flood the speech queue.
  announce(text) {
    this.pending.push(text);
    if (this.announceTimer) return;
    const flush = () => {
      this.live.textContent = this.pending.join(" ");
      this.pending = [];
      this.announceTimer = setTimeout(() => {
        this.announceTimer = null;
        if (this.pending.length > 0) flush();
      }, 1500);
    };
    flush();
  }

  // Announce what changed since the last render. The first render after a
  // reset only records the baseline.
  announceChanges(snap, fresh) {
    const prev = this.prev;
    const cut = new Set(snap.nodes.filter((n) => n.partitioned).map((n) => n.id));
    const leader = snap.leaders.length > 0 ? snap.leaders[0] : null;
    if (prev) {
      for (const id of cut) if (!prev.cut.has(id)) this.announce(`N${id} partitioned.`);
      for (const id of prev.cut) if (!cut.has(id)) this.announce(`N${id} healed.`);
      if (leader !== prev.leader) {
        const epoch = Math.max(0, ...snap.nodes.map((n) => n.epoch));
        this.announce(leader == null ? "No leader." : `N${leader} is leader, epoch ${epoch}.`);
      }
      if (fresh.some((s) => s.action.kind === "Drop")) this.announce("Message dropped.");
    }
    this.prev = { cut, leader };
  }

  // ---- lifecycle ------------------------------------------------------------

  reset() {
    this.pause();
    if (this.pg) {
      this.pg.reset(this.voters);
    } else {
      this.pg = new Playground(this.voters);
    }
    this.seenSteps = 0;
    this.timeline.innerHTML = "";
    this.prev = null;
    this.render();
  }

  togglePlay() {
    if (this.playing) {
      this.pause();
    } else {
      this.play();
    }
  }

  play() {
    if (this.playing) return;
    this.playing = true;
    this.playBtn.textContent = "❚❚ Pause";
    this.playBtn.classList.add("cp-active");
    const tick = () => {
      if (!this.playing) return;
      const progressed = this.step();
      // When the cluster goes quiet, keep idling slowly so a later fault still
      // animates, but stop hammering.
      this.timer = setTimeout(tick, progressed ? this.speedMs : this.speedMs * 2);
    };
    this.timer = setTimeout(tick, this.speedMs);
  }

  pause() {
    this.playing = false;
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
    if (this.playBtn) {
      this.playBtn.textContent = "▶ Play";
      this.playBtn.classList.remove("cp-active");
    }
  }

  step() {
    const progressed = this.pg.step();
    this.render();
    return progressed;
  }

  // Run a one-shot fault closure, then re-render.
  act(fn) {
    this.pause();
    fn();
    this.render();
  }

  partitionLeader() {
    const snap = this.snapshot();
    const leader = snap.leaders[0];
    if (leader == null) return;
    this.act(() => this.pg.partition(leader));
  }

  toggleNode(id) {
    const snap = this.snapshot();
    const node = snap.nodes.find((n) => n.id === id);
    if (!node) return;
    this.act(() => {
      if (node.partitioned) this.pg.heal(id);
      else this.pg.partition(id);
    });
  }

  healAll() {
    const cut = this.snapshot().nodes.filter((n) => n.partitioned);
    if (cut.length > 0) this.act(() => cut.forEach((n) => this.pg.heal(n.id)));
  }

  // ---- rendering ------------------------------------------------------------

  snapshot() {
    return JSON.parse(this.pg.state());
  }

  render() {
    const snap = this.snapshot();
    this.drawCluster(snap);
    this.drawStatus(snap);
    this.announceChanges(snap, this.appendTimeline(snap.step_count));
  }

  // The viewBox is the column's pixel size, so text is never scaled: the ring
  // shrinks on a phone instead, and message labels that would not fit clear of
  // the nodes and of each other are left off (the arrow stays, its hover title
  // names the event).
  drawCluster(snap) {
    this.lastSnap = snap;
    const W = this.svg.getBoundingClientRect().width || 420;
    this.width = W;
    const { pos, height } = layoutRing(snap.nodes, W);
    this.svg.setAttribute("viewBox", `0 0 ${W} ${height}`);

    // Nodes persist across redraws so keyboard focus survives Play.
    if (snap.nodes.some((node) => !this.nodeEls.has(node.id)) || this.nodeEls.size !== snap.nodes.length) {
      this.nodeLayer.replaceChildren();
      this.nodeEls.clear();
      for (const node of snap.nodes) {
        const parts = createNode(node.id, (id) => this.toggleNode(id));
        this.nodeEls.set(node.id, parts);
        this.nodeLayer.appendChild(parts.g);
      }
    }
    for (const node of snap.nodes) updateNode(this.nodeEls.get(node.id), node, pos.get(node.id));

    // Decorative: the nodes carry the state, the timeline lists the events.
    this.arcLayer.replaceChildren();
    this.labelLayer.replaceChildren();
    this.arcLayer.setAttribute("aria-hidden", "true");
    this.labelLayer.setAttribute("aria-hidden", "true");
    const taken = [];
    for (const node of snap.nodes) {
      const { x, y } = pos.get(node.id);
      taken.push({ x: x - NODE_R - 2, y: y - NODE_R - 2, w: 2 * NODE_R + 4, h: 2 * NODE_R + 4 });
      const { above } = pos.get(node.id);
      taken.push({ x: x - 28, y: above ? y - NODE_R - CAPTION_H : y + NODE_R, w: 56, h: CAPTION_H }); // log / hwm caption
      if (node.partitioned) taken.push({ x: x + NODE_R - 4, y: y - NODE_R, w: 20, h: 20 });
    }
    const pairCount = new Map();
    for (const m of snap.in_flight) {
      const from = pos.get(m.src);
      const to = pos.get(m.dst);
      if (!from || !to) continue;
      const key = `${m.src}-${m.dst}`;
      const k = pairCount.get(key) || 0;
      pairCount.set(key, k + 1);
      messageArc(this.arcLayer, this.labelLayer, from, to, m.event, k, taken, W, height);
    }
  }

  drawStatus(snap) {
    const leaders =
      snap.leaders.length === 0
        ? "<em>none</em>"
        : snap.leaders.map((l) => `N${l}`).join(", ");
    const epoch = Math.max(0, ...snap.nodes.map((n) => n.epoch));
    this.status.innerHTML =
      `<span><b>clock</b> ${snap.clock_ms} ms</span>` +
      `<span><b>leader</b> ${leaders}</span>` +
      `<span><b>epoch</b> ${epoch}</span>` +
      `<span><b>in&nbsp;flight</b> ${snap.in_flight.length}</span>` +
      `<span><b>steps</b> ${snap.step_count}</span>`;
  }

  appendTimeline(stepCount) {
    if (stepCount <= this.seenSteps) {
      // Reset detected (or nothing new).
      if (stepCount < this.seenSteps) {
        this.timeline.innerHTML = "";
        this.seenSteps = 0;
      } else {
        return [];
      }
    }
    const fresh = JSON.parse(this.pg.timeline_since(this.seenSteps));
    for (const s of fresh) {
      const li = el("li", "cp-event");
      const icon = ACTION_ICON[s.action.kind] || "•";
      li.innerHTML =
        `<span class="cp-event-icon">${icon}</span>` +
        `<span class="cp-event-clock">${s.clock_ms}ms</span>` +
        `<span class="cp-event-note">${escapeHtml(s.note)}</span>`;
      this.timeline.appendChild(li);
    }
    this.seenSteps = stepCount;
    // Keep the latest event in view.
    this.timeline.scrollTop = this.timeline.scrollHeight;
    return fresh;
  }
}

// ---- SVG helpers ------------------------------------------------------------

const NODE_R = 28;
// The two-line log / hwm caption.
const CAPTION_H = 34;

// Node centres on a ring sized to the column, in screen pixels, plus the
// height that fits the ring with each node's two-line caption on the outside
// of the ring: above the nodes of the upper half, below the others. Arrows run
// between the nodes, inside the ring, so they never cross a caption.
function layoutRing(nodes, W) {
  const n = nodes.length;
  const angle = (i) => -Math.PI / 2 + (i * 2 * Math.PI) / n;
  const reach = Math.max(...nodes.map((_, i) => Math.abs(Math.cos(angle(i)))));
  const drop = Math.max(...nodes.map((_, i) => Math.sin(angle(i))));
  const r = Math.min(150, Math.max(56, (W / 2 - NODE_R - 6) / reach));
  const cy = NODE_R + CAPTION_H + 4 + r;
  const pos = new Map();
  nodes.forEach((node, i) => {
    pos.set(node.id, { x: W / 2 + r * Math.cos(angle(i)), y: cy + r * Math.sin(angle(i)), above: Math.sin(angle(i)) < -0.01 });
  });
  return { pos, height: Math.ceil(cy + r * drop + NODE_R + CAPTION_H + 4) };
}

function svgEl(tag, cls) {
  const e = document.createElementNS(SVG_NS, tag);
  if (cls) e.setAttribute("class", cls);
  return e;
}

// The parts of a node badge that never change. `updateNode` fills in the rest,
// so the same elements (and keyboard focus) survive every redraw.
function createNode(id, onClick) {
  const g = svgEl("g");
  g.style.cursor = "pointer";
  g.dataset.node = String(id);
  // A node is a toggle: the same action for a click, Enter or Space.
  g.setAttribute("role", "button");
  g.setAttribute("tabindex", "0");
  g.addEventListener("click", () => onClick(id));
  g.addEventListener("keydown", (ev) => {
    if (ev.key !== "Enter" && ev.key !== " ") return;
    ev.preventDefault();
    onClick(id);
  });

  const circle = svgEl("circle", "cp-node-bg");
  circle.setAttribute("r", String(NODE_R));
  g.appendChild(circle);

  const idText = svgEl("text", "cp-node-id");
  idText.setAttribute("text-anchor", "middle");
  idText.setAttribute("y", "-3");
  idText.textContent = `N${id}`;

  const role = svgEl("text", "cp-node-role");
  role.setAttribute("text-anchor", "middle");
  role.setAttribute("y", "11");

  // Log and high-watermark caption under the node, on two lines so it stays
  // narrower than the gap between neighbours on a phone.
  const log = svgEl("text", "cp-node-log");
  log.setAttribute("text-anchor", "middle");
  const logLine = svgEl("tspan");
  logLine.setAttribute("x", "0");
  const hwmLine = svgEl("tspan");
  hwmLine.setAttribute("x", "0");
  log.append(logLine, hwmLine);

  // Beside the node, clear of the caption whichever side that is on.
  const cut = svgEl("text", "cp-node-cut");
  cut.setAttribute("x", String(NODE_R - 2));
  cut.setAttribute("y", String(-(NODE_R - 12)));
  cut.textContent = "✂";

  g.append(idText, role, log, cut);
  return { g, role, logLine, hwmLine };
}

function updateNode({ g, role, logLine, hwmLine }, node, p) {
  const style = ROLE_STYLE[node.role] || ROLE_STYLE.Unattached;
  g.setAttribute("class", `cp-node cp-${style.cls}${node.partitioned ? " cp-partitioned" : ""}`);
  g.setAttribute("transform", `translate(${p.x}, ${p.y})`);
  g.setAttribute(
    "aria-label",
    `N${node.id}, ${node.role}, epoch ${node.epoch}. ` +
      (node.partitioned ? "Partitioned; activate to heal." : "Activate to partition."),
  );
  role.textContent = `${style.glyph} e${node.epoch}`;
  // Outside the ring, from the rim outward at a 14 px pitch.
  logLine.setAttribute("y", String(p.above ? -(NODE_R + 20) : NODE_R + 14));
  hwmLine.setAttribute("y", String(p.above ? -(NODE_R + 6) : NODE_R + 28));
  logLine.textContent = `log ${node.log_len}`;
  hwmLine.textContent = `hwm ${node.hwm}`;
}

// Where along the arc a label may sit, best first.
const LABEL_SPOTS = [0.5, 0.32, 0.68, 0.2, 0.8];

const overlaps = (a, b) =>
  a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;

// A curved arrow from `from` to `to`, nudged outward by `k` so multiple
// messages between the same pair don't perfectly overlap. Its label goes at the
// first spot along the arc that clears `taken` (nodes and earlier labels) and
// the diagram edges; if none does, the arrow goes unlabelled.
function messageArc(arcLayer, labelLayer, from, to, eventLabel, k, taken, W, H) {
  const g = svgEl("g", "cp-msg");

  // Trim endpoints to the node radius so arrows touch the rim, not the centre.
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const len = Math.hypot(dx, dy) || 1;
  const ux = dx / len;
  const uy = dy / len;
  const rad = NODE_R + 2;
  const sx = from.x + ux * rad;
  const sy = from.y + uy * rad;
  const ex = to.x - ux * rad;
  const ey = to.y - uy * rad;

  // Control point perpendicular to the chord for a gentle curve.
  const mx = (sx + ex) / 2;
  const my = (sy + ey) / 2;
  const off = 16 + k * 14;
  const px = mx + (-uy) * off;
  const py = my + ux * off;

  const path = svgEl("path", "cp-msg-path");
  path.setAttribute("d", `M ${sx} ${sy} Q ${px} ${py} ${ex} ${ey}`);
  path.setAttribute("marker-end", "url(#cp-arrow)");
  const title = svgEl("title");
  title.textContent = eventLabel;
  g.append(title, path);
  arcLayer.appendChild(g);

  const text = svgEl("text", "cp-msg-label");
  text.setAttribute("text-anchor", "middle");
  text.setAttribute("dy", "0.35em");
  text.textContent = eventLabel;
  labelLayer.appendChild(text);
  let w = eventLabel.length * 6.4;
  try {
    w = text.getBBox().width || w;
  } catch {
    // Not rendered (hidden): the estimate above will do.
  }
  for (const t of LABEL_SPOTS) {
    const a = (1 - t) * (1 - t);
    const b = 2 * (1 - t) * t;
    const c = t * t;
    const x = a * sx + b * px + c * ex;
    const y = a * sy + b * py + c * ey;
    const box = { x: x - w / 2 - 2, y: y - 8, w: w + 4, h: 16 };
    if (box.x < 0 || box.y < 0 || box.x + box.w > W || box.y + box.h > H) continue;
    if (taken.some((o) => overlaps(box, o))) continue;
    text.setAttribute("x", String(x));
    text.setAttribute("y", String(y));
    taken.push(box);
    return;
  }
  text.remove();
}

function arrowMarker() {
  const defs = document.createElementNS(SVG_NS, "defs");
  const marker = document.createElementNS(SVG_NS, "marker");
  marker.setAttribute("id", "cp-arrow");
  marker.setAttribute("viewBox", "0 0 10 10");
  marker.setAttribute("refX", "9");
  marker.setAttribute("refY", "5");
  marker.setAttribute("markerWidth", "7");
  marker.setAttribute("markerHeight", "7");
  marker.setAttribute("orient", "auto-start-reverse");
  const tip = document.createElementNS(SVG_NS, "path");
  tip.setAttribute("d", "M 0 0 L 10 5 L 0 10 z");
  tip.setAttribute("class", "cp-arrow-tip");
  marker.appendChild(tip);
  defs.appendChild(marker);
  return defs;
}

// ---- DOM helpers ------------------------------------------------------------

function el(tag, cls) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  return e;
}

function button(text, cls, onClick) {
  const b = el("button", `cp-btn ${cls}`.trim());
  b.type = "button";
  b.textContent = text;
  b.addEventListener("click", onClick);
  return b;
}

function label(text) {
  const l = el("span", "cp-label");
  l.textContent = text;
  return l;
}

function escapeHtml(s) {
  return s.replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[
        c
      ],
  );
}

// ---- boot -------------------------------------------------------------------

async function boot() {
  const root = document.getElementById("krabka-playground");
  if (!root) return;
  try {
    await init();
    const ui = new PlaygroundUI(root);
    ui.reset();
  } catch (err) {
    root.innerHTML =
      `<p class="cp-error">The consensus playground failed to load: ${escapeHtml(
        String(err),
      )}</p>`;
    // eslint-disable-next-line no-console
    console.error("krabka playground failed to initialise", err);
  }
}

boot();
